-- [12XX] = {['message'] = "M", ['category'] = X, ['location'] = Y, ['channel'] = CHAT_CHANNEL_ZONE},

function CyroChat:SetUpCommands()
	SLASH_COMMANDS["/cctest"] = function (extra)
		CyroChat.printMessages = false

		d("/cctest started!")
		
		local pieces = CyroChat.string_split(extra)
		local printMessages = false
		local startAtIndex = 1
		local endAtIndex = #CyroChat.unitTests

		if #pieces >= 1 then
			if pieces[1] == 'true' then
				printMessages = true
			end

			if pieces[2] ~= nil then
				startAtIndex = tonumber(pieces[2])
			end

			if pieces[3] ~= nil then
				endAtIndex = tonumber(pieces[3])
			end
		end

		local success = 0
		local unitTestSuccess = false

		for currentIndex, messageInfo in pairs(CyroChat.unitTests) do
			if currentIndex > endAtIndex then
				break
			end
		
			if currentIndex < startAtIndex then
				
			else
				unitTestSuccess = false
				unitTestSuccess = CyroChat.unitTest(messageInfo.message, messageInfo.category, messageInfo.location, messageInfo.channel, printMessages)

				if unitTestSuccess == false then
					break
				elseif unitTestSuccess == true then
					success = success + 1
				end
			end
		end

		d("Completed: " .. success .. " / " .. (endAtIndex - (startAtIndex-1)))

		CyroChat.printMessages = false
	end

	SLASH_COMMANDS["/ccdistance"] = function (extra)
		d("Starting /ccdistance")
		local pieces = CyroChat.string_split(extra)
		local returnedValue = CyroChat.EditDistance(pieces[1], pieces[2])
		d("Returned: "..tostring(returnedValue))
	end
end

function CyroChat.unitTest(message, messageCategoryId, messageLocation, messageChannel, printMessages)
	local fakeLocation = nil

	if messageChannel == CHAT_CHANNEL_SAY then
		fakeLocation = messageLocation
	end

	local categoryId = CyroChat.checkMessage(message, messageChannel, 'Aewenil', '@aldericon', true, fakeLocation)
	local locationId = CyroChat.unitTestLocation(message, messageChannel, fakeLocation)

	local checkTable = true

	--[[if messageChannel == CHAT_CHANNEL_SAY then
		checkTable = true
	elseif type(messageLocation) == 'table' then
		checkTable = false
				
		for i=1, #messageLocation do
			if messageLocation[i] == locationId then
				checkTable = true
				break
			end
		end
	elseif messageLocation ~= locationId then
		checkTable = false
	end]]

	if messageChannel == CHAT_CHANNEL_SAY then
		checkTable = true
	elseif type(messageLocation) == 'table' then
		messageCategoryId = nil

		if locationId ~= nil then
			checkTable = false
		end
	elseif messageLocation ~= locationId then
		checkTable = false
	end

	if categoryId ~= messageCategoryId or checkTable == false then
		if printMessages == true then
			CyroChat.printMessages = true
			CyroChat.checkMessage(message, messageChannel, 'Aewenil', '@aldericon', true, fakeLocation)
			CyroChat.unitTestLocation(message, messageChannel, fakeLocation)
		end

		if categoryId ~= messageCategoryId and checkTable == false then
			if type(messageLocation) == 'table' then
				d("Message: '" .. message .. "' got category " .. tostring(categoryId) .. " but belongs in category " .. tostring(messageCategoryId) .. " and got location '".. tostring(CyroChat.keeps[locationId]) .. "' but belongs in location '{MULTIPLE}'")
			else
				d("Message: '" .. message .. "' got category " .. tostring(categoryId) .. " but belongs in category " .. tostring(messageCategoryId) .. " and got location '".. tostring(CyroChat.keeps[locationId]) .. "' but belongs in location '" .. tostring(CyroChat.keeps[messageLocation]) .. "'")
			end
		elseif categoryId ~= messageCategoryId then
			d("Message: '" .. message .. "' got category " .. tostring(categoryId) .. " but belongs in category " .. tostring(messageCategoryId))
		elseif checkTable == false then
			if type(messageLocation) == 'table' then
				d("Message: '" .. message .. "' got location '" .. tostring(CyroChat.keeps[locationId]) .. "' but belongs in location '{MULTIPLE}'")
			else
				d("Message: '" .. message .. "' got location '" .. tostring(CyroChat.keeps[locationId]) .. "' but belongs in location '" .. tostring(CyroChat.keeps[messageLocation]) .. "'")
			end
		end

		if messageChannel == CHAT_CHANNEL_ZONE then
			CHAT_SYSTEM:StartTextEntry(message, CHAT_CHANNEL_SAY)
		end

		return false
	end

	return true
end

function CyroChat.unitTestLocation(text, channelType, fakeLocation)
	if CyroChat.printMessages == true then
		d("Inside unitTestLocation")
	end

	if CyroChat.usePlayerLocation == true then
		if channelType == CHAT_CHANNEL_YELL or channelType == CHAT_CHANNEL_SAY then
			CyroChat.messageUsedPlayerLocation = true

			return fakeLocation
		end
	end

	text = CyroChat.messageChanges(text)

	if CyroChat.printMessages == true then
		d("After message changes: "..text)
	end

	text = CyroChat.clearOutChatMessage(text)

	--[[if CyroChat.printMessages == true then
		d("After clear out: "..text)
	end]]

	if text == '' then
		return nil
	end

	local foundLocation = CyroChat.findLocation(text, CyroChat.string_split(text))

	--[[if CyroChat.printMessages == true then
		d("Found Location: "..tostring(foundLocation))
	end]]

	if foundLocation == nil then
		-- if the user yells/says, same location as we are, so we can get the location from our current location
		if channelType == CHAT_CHANNEL_YELL or channelType == CHAT_CHANNEL_SAY then
			foundLocation = CyroChat.playerZoneId
		end
	end

	if foundLocation == nil or foundLocation == '' then
		return nil
	end

	return foundLocation
end
